    function testPlay(uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        require(amt == 10);
        require(address(this).balance >= amt);
        c.play{value: amt}(); if (__ESBMC_reverted()) return;
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
