pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _testPlay(uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amt = 10;
        vm.assume(address(this).balance >= amt);
        try c.play{value: amt}() {} catch { return; }
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        assertTrue((c.pot() == 0) == (random == 0));
    }

    function testFuzz_testPlay(uint256 amt) public {
        _testPlay(amt);
    }

    receive() external payable {}

    fallback() external payable {}
}
